var rng *concurrentRNG

type concurrentRNG struct {
	mu  sync.Mutex
	rng *rand.Rand
}

func (r *concurrentRNG) Intn(n int) int {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.rng.Intn(n)
}

func init() {
	rng = &concurrentRNG{
		rng: rand.New(rand.NewSource(314159)),
	}
}

func TestBasicSeqnoValidator1(t *testing.T) {
