		_ = newReplayActor(t, ctx, hosts[19])

		var msgs []*Subscription
		for _, ps := range psubs {
			subch, err := ps.Subscribe("foobar")
			if err != nil {
				t.Fatal(err)
			}

			msgs = append(msgs, subch)
